INSERT INTO geoip.autonomous_system (
autonomous_system_number, autonomous_system_organization
) VALUES

    (
    #{asn.autonomousSystemNumber}, #{asn.autonomousSystemOrganization}
    )

ON CONFLICT (autonomous_system_number) DO NOTHING

INSERT INTO geoip.asn_block (
network, autonomous_system_number
) VALUES

    (
    CAST(#{asnBlock.network} AS cidr), #{asnBlock.autonomousSystemNumber}
    )

ON CONFLICT (network) DO NOTHING
